  `idCredorDevedor` int DEFAULT NULL COMMENT 'ID do credor ou devedor',
  `observacoes` text COLLATE utf8mb4_unicode_ci,
  `dataInclusao` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
