DROP TABLE IF EXISTS `TbFinanceiroFatura`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `TbFinanceiroFatura` (
  `idFatura` int NOT NULL AUTO_INCREMENT,
  `idEmpresa` int NOT NULL,
  `dataInicio` date NOT NULL COMMENT 'Data de início do período da fatura',
  `dataFim` date NOT NULL COMMENT 'Data de fim do período da fatura',
  `dataVencimento` date NOT NULL COMMENT 'Data de vencimento da cobrança gerada',
  `valorTotal` decimal(15,2) NOT NULL,
  `status` enum('ABERTA','AGUARDANDO_DEVOLUCAO','FECHADA','PAGA','PAGA_PARCIALMENTE','CANCELADA') NOT NULL DEFAULT 'ABERTA',
  `idLancamento` int DEFAULT NULL COMMENT 'Link para o lançamento financeiro gerado',
  `dataInclusao` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `dataAlteracao` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `valorPago` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT 'Valor total já pago para esta fatura (soma dos pagamentos por item)',
  `desconto` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT 'Valor de desconto aplicado na fatura (valor fixo em reais)',
  `valorTotalBruto` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT 'Valor total bruto da fatura antes de aplicar o desconto (soma de todas as ordens de serviço)',
  `anotacoes` text COMMENT 'Anotações sobre a fatura para lembretes nas interações com os dentistas',
  `idFaturaOriginal` int DEFAULT NULL,
  `descricao` varchar(255) DEFAULT NULL,
  `descontoDevolucao` decimal(15,2) NOT NULL DEFAULT '0.00',
  PRIMARY KEY (`idFatura`),
  KEY `IX_Fatura_Empresa` (`idEmpresa`),
  KEY `IX_Fatura_Lancamento` (`idLancamento`),
  KEY `FK_FinanceiroFatura_Original` (`idFaturaOriginal`),
  CONSTRAINT `FK_Fatura_Lancamento` FOREIGN KEY (`idLancamento`) REFERENCES `TbFinanceiroLancamento` (`idLancamento`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `FK_FinanceiroFatura_Original` FOREIGN KEY (`idFaturaOriginal`) REFERENCES `TbFinanceiroFatura` (`idFatura`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=740 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
