DROP TABLE IF EXISTS `TbFinanceiroFornecedor`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `TbFinanceiroFornecedor` (
  `idFornecedor` int NOT NULL AUTO_INCREMENT,
  `cnpj` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'CNPJ (texto livre)',
  `cpf` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'CPF (texto livre)',
  `razaoSocial` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nomeFantasia` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `telefone` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cep` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `logradouro` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `numero` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `complemento` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bairro` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cidade` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `uf` char(2) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ativo` tinyint(1) NOT NULL DEFAULT '1',
  `idCategoria` int DEFAULT NULL COMMENT 'Categoria de despesa padrão do fornecedor',
  `dataInclusao` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `dataAlteracao` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`idFornecedor`),
  KEY `IX_Fornecedor_Ativo` (`ativo`),
  KEY `IX_Fornecedor_RazaoSocial` (`razaoSocial`(100)),
  KEY `IX_Fornecedor_Categoria` (`idCategoria`),
  CONSTRAINT `FK_Fornecedor_Categoria` FOREIGN KEY (`idCategoria`) REFERENCES `TbFinanceiroCategoria` (`idCategoria`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=79 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Fornecedores para contas a pagar (vinculados a lançamentos de despesa)';
/*!40101 SET character_set_client = @saved_cs_client */;

