-- ==========================================
-- Tabela TbFinanceiroLancamento
-- ==========================================
-- Table structure for table `TbFinanceiroLancamento`
--

DROP TABLE IF EXISTS `TbFinanceiroLancamento`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `TbFinanceiroLancamento` (
  `idLancamento` int NOT NULL AUTO_INCREMENT,
  `descricao` varchar(255) NOT NULL,
  `tipo` enum('RECEITA','DESPESA') NOT NULL,
  `valorTotal` decimal(15,2) NOT NULL,
  `totalParcelas` int NOT NULL DEFAULT '1',
  `dataCompetencia` date NOT NULL,
  `dataEmissao` date DEFAULT NULL COMMENT 'Data de emissão do lançamento',
  `numeroDocumento` varchar(100) DEFAULT NULL COMMENT 'Número do documento (nota fiscal, boleto, recibo etc.) - opcional',
  `status` enum('PENDENTE','PARCIALMENTE_PAGO','PAGO','CANCELADO') NOT NULL DEFAULT 'PENDENTE',
  `idOrdemServico` int DEFAULT NULL,
  `idFatura` int DEFAULT NULL,
  `idClienteFornecedor` int DEFAULT NULL,
  `idFornecedor` int DEFAULT NULL,
  `idCategoria` int DEFAULT NULL,
  `dataInclusao` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`idLancamento`),
  KEY `IX_Lancamento_OrdemServico` (`idOrdemServico`),
  KEY `IX_Lancamento_Fatura` (`idFatura`),
  KEY `IX_Lancamento_Categoria` (`idCategoria`),
  KEY `IX_Lancamento_Fornecedor` (`idFornecedor`),
  CONSTRAINT `FK_Lancamento_Categoria` FOREIGN KEY (`idCategoria`) REFERENCES `TbFinanceiroCategoria` (`idCategoria`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `FK_Lancamento_Fatura` FOREIGN KEY (`idFatura`) REFERENCES `TbFinanceiroFatura` (`idFatura`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `FK_Lancamento_Fornecedor` FOREIGN KEY (`idFornecedor`) REFERENCES `TbFinanceiroFornecedor` (`idFornecedor`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `FK_Lancamento_OrdemServico` FOREIGN KEY (`idOrdemServico`) REFERENCES `TbOrdemServico` (`idOrdemServico`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3486 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

