DROP TABLE IF EXISTS `TbFinanceiroMovimentacao`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `TbFinanceiroMovimentacao` (
  `idMovimentacao` int NOT NULL AUTO_INCREMENT,
  `idConta` int NOT NULL,
  `tipo` enum('CREDITO','DEBITO') NOT NULL,
  `valor` decimal(15,2) NOT NULL,
  `valorAcrescimo` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT 'Juros/multa em recebimentos (separado do principal em valor)',
  `descricao` varchar(255) NOT NULL,
  `dataMovimentacao` datetime NOT NULL,
  `idParcelaOrigem` int DEFAULT NULL,
  `idAgrupadorTransferencia` varchar(36) DEFAULT NULL,
  PRIMARY KEY (`idMovimentacao`),
  KEY `IX_Movimentacao_Conta` (`idConta`),
  CONSTRAINT `FK_Movimentacao_Conta` FOREIGN KEY (`idConta`) REFERENCES `TbFinanceiroConta` (`idConta`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3396 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
