-- Tabela TbFinanceiroParcela
-- ==========================================
-- Table structure for table `TbFinanceiroParcela`
--

DROP TABLE IF EXISTS `TbFinanceiroParcela`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `TbFinanceiroParcela` (
  `idParcela` int NOT NULL AUTO_INCREMENT,
  `idLancamento` int NOT NULL,
  `numeroParcela` int NOT NULL,
  `valor` decimal(15,2) NOT NULL,
  `dataVencimento` date NOT NULL,
  `dataPagamento` date DEFAULT NULL,
  `status` enum('ABERTO','PAGO','VENCIDO','CANCELADO') NOT NULL DEFAULT 'ABERTO',
  `meioPagamento` enum('DINHEIRO','CARTAO_CREDITO','CARTAO_DEBITO','CHEQUE','BOLETO','TRANSFERENCIA','PIX') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `dadosAdicionais` json DEFAULT NULL,
  `numeroBoleto` varchar(50) DEFAULT NULL COMMENT 'Número do boleto bancário',
  `codigoBarras` varchar(100) DEFAULT NULL COMMENT 'Código de barras do boleto',
  `idMovimentacao` int DEFAULT NULL,
  `valorPago` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT 'Valor total já pago para esta parcela',
  `valorAcrescimoAcumulado` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT 'Soma dos acréscimos (juros/multa) nos recebimentos desta parcela (RECEITA)',
  `gerarJuros` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Indica se a parcela gera juros ao atrasar',
  PRIMARY KEY (`idParcela`),
  KEY `IX_Parcela_Lancamento` (`idLancamento`),
  KEY `IX_Parcela_Movimentacao` (`idMovimentacao`),
  CONSTRAINT `FK_Parcela_Lancamento` FOREIGN KEY (`idLancamento`) REFERENCES `TbFinanceiroLancamento` (`idLancamento`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `FK_Parcela_Movimentacao` FOREIGN KEY (`idMovimentacao`) REFERENCES `TbFinanceiroMovimentacao` (`idMovimentacao`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3504 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

