DROP TABLE IF EXISTS `TbOrdemServicoItem`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `TbOrdemServicoItem` (
  `idOrdemServicoItem` int NOT NULL AUTO_INCREMENT,
  `idOrdemServico` int DEFAULT NULL,
  `descricao` varchar(255) NOT NULL,
  `valor` decimal(11,2) DEFAULT NULL,
  `quantidade` int NOT NULL,
  `valorTotal` decimal(11,2) DEFAULT NULL,
  `idReferencia` int NOT NULL,
  `tipoCobranca` varchar(100) NOT NULL,
  `ativo` tinyint(1) NOT NULL DEFAULT '1',
  `idUsuarioCadastro` int NOT NULL,
  `dataInclusao` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `dataAlteracao` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `dataExclusao` datetime DEFAULT NULL,
  `status` enum('PENDENTE','FATURADO','DEVOLUCAO_SOLICITADA','DEVOLVIDO','DEVOLUCAO_CANCELADA','PAGO','CANCELADO') NOT NULL DEFAULT 'PENDENTE' COMMENT 'Status do item dentro da Ordem de Serviço',
  `idProfissional` int DEFAULT NULL COMMENT 'ID do profissional associado ao item',
  `idPaciente` int DEFAULT NULL COMMENT 'ID do paciente associado ao item',
  `valorPago` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT 'Valor total já pago para este item',
  `quantidadeDevolvida` int NOT NULL DEFAULT '0' COMMENT 'Quantidade de itens em processo de devolução',
  PRIMARY KEY (`idOrdemServicoItem`),
  CONSTRAINT `TbOrdemServicoItem_chk_1` CHECK ((`ativo` in (0,1)))
) ENGINE=InnoDB AUTO_INCREMENT=11610 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
